package com.nightbeam.donutshards.event;
import org.bukkit.event.*;import java.util.UUID;
public final class ShardBalanceChangeEvent extends Event implements Cancellable {private static final HandlerList HANDLERS=new HandlerList();private final UUID player;private final long oldBalance,newBalance;private boolean cancelled;public ShardBalanceChangeEvent(UUID player,long oldBalance,long newBalance,boolean async){super(async);this.player=player;this.oldBalance=oldBalance;this.newBalance=newBalance;}public UUID player(){return player;}public long oldBalance(){return oldBalance;}public long newBalance(){return newBalance;}public boolean isCancelled(){return cancelled;}public void setCancelled(boolean v){cancelled=v;}public HandlerList getHandlers(){return HANDLERS;}public static HandlerList getHandlerList(){return HANDLERS;}}
